function hitPlayers(p,ox,oy,oz,dx,dy,dz,t0,t1,skip){let best=null;for(const q of players){if(q===p||!q.alive||q.inPlane||skip&&skip.has(q))continue;if(Math.hypot(q.x-ox,q.z-oz)>t1+2)continue;for(const[part,cx,cy,cz,r]of partsOf(q)){const lx=cx-ox,ly=cy-oy,lz=cz-oz,t=lx*dx+ly*dy+lz*dz;if(t<t0||t>t1)continue;const d2=lx*lx+ly*ly+lz*lz-t*t;if(d2<r*r){const th=t-Math.sqrt(r*r-d2);if(!best||th<best.t)best={t:th,q,part}}}}return best}
