  if(W.cls==='melee'){if(p.fireCd>0)return;p.fireCd=.5;evt({k:'swing',p:p.id});const dx=-Math.sin(p.yaw)*Math.cos(p.pitch),dy=Math.sin(p.pitch),dz=-Math.cos(p.yaw)*Math.cos(p.pitch);const h=hitPlayers(p,p.x,eyeY(p),p.z,dx,dy,dz,0,1.9);if(h){const back=Math.cos(h.q.yaw-p.yaw)>.55;hurtP(h.q,back?(p.inp.alt?180:90):(p.inp.alt?65:40),p,'knife',false);evt({k:'blood',x:h.q.x,y:eyeY(h.q)-.4,z:h.q.z,by:p.id})}return}
