  if(by&&by!==q&&(ROY||by.team!==q.team)){by.kills++;if(!ROY)by.money=Math.min(16000,by.money+(w==='he'||w==='molotov'||w==='incgren'?300:(WPN[w]&&WPN[w].kill||300)))}for(const id in q.dmgBy){const a=pById(+id);if(a&&a!==by&&q.dmgBy[id]>=40&&(ROY||a.team!==q.team))a.assists++}
