/* ---------------- buying ---------------- */
function canBuy(p){return !ROY&&p.alive&&round.buyT>0&&round.phase!=='post'&&inBuyZone(p)}
function buy(p,id){if(!canBuy(p))return false;const W=WPN[id],G=GEAR[id];const item=W||G;if(!item)return false;let price=item.price;if(id==='vesthelm'&&p.armor>=100)price=350;if(!price||p.money<price)return false;if(item.side&&item.side!==p.team)return false;
  if(G){if(id==='vest'){if(p.armor>=100)return false;p.armor=100}else if(id==='vesthelm'){if(p.armor>=100&&p.helmet)return false;p.armor=100;p.helmet=true}else if(id==='kit'){if(p.kit)return false;p.kit=true}}
  else if(W.slot===4){p.inv.g=p.inv.g||[];const cnt=p.inv.g.filter(x=>x===id).length;if(p.inv.g.length>=4||cnt>=(W.max||1))return false;p.inv.g.push(id)}
  else{if(p.inv[W.slot]===id)return false;const def=p.team==='T'?'glock':'usp';if(p.inv[W.slot]&&p.inv[W.slot]!==def)dropGun(p,p.inv[W.slot]);giveW(p,id);equip(p,id)}
  p.money-=price;return true}
function botBuy(p){const m=p.money,t=p.team,eco=m<2000&&round.n!==1&&round.n!==HALF+1;if(eco){if(m>=500&&Math.random()<.4)buy(p,'p250');return}
  if(round.n===1||round.n===HALF+1){if(Math.random()<.5)buy(p,'vest');else if(Math.random()<.5)buy(p,t==='T'?'tec9':'p250');else buy(p,'flash');return}
  if(m>=4750+1000&&Math.random()<.18)buy(p,'awp');else if(m>=3700)buy(p,t==='T'?'ak':(Math.random()<.5?'m4a4':'m4a1s'));else if(m>=2900)buy(p,t==='T'?'galil':'famas');else if(m>=1800)buy(p,t==='T'?'mac10':'mp9');
  buy(p,'vesthelm');buy(p,'vest');if(t==='CT')buy(p,'kit');for(const g2 of[pick(['smoke','flash']),'flash','he',t==='T'?'molotov':'incgren'])if(p.money>=600&&Math.random()<.55)buy(p,g2)}
